import { Component } from '@angular/core';
import { Pienso } from 'src/app/models/pienso';
import { PiensoService } from 'src/app/services/pienso.service';

@Component({
  selector: 'app-categorias',
  templateUrl: './categorias.component.html',
  styleUrls: ['./categorias.component.css']
})
export class CategoriasComponent {

  precioSeleccionado:string|null = null
  pesoSeleccionado:string|null = null


  activadoPrecio: boolean=false;
  activadoPeso: boolean=false;

  filtros = {
    precio: '',
    peso: '',
    tipoAnimal: ''
  };

  productosAnteriores: Pienso[] = [];

  //CATEGORIAS FILTROS PIENSOS
  constructor(private piensoService: PiensoService){}


  //BOTON VER TODOS LOS PRODUCTOS
  mostrarTodosLosProductos() {
    this.resetearFiltros(); //borras filtros
    this.actualizarProductos(); //y muestas de nuevo
  }


  resetearFiltros() { //eliminas todos los productos a vacio
    this.filtros = { precio: '', peso: '', tipoAnimal: ''};
  }


  aplicarFiltros() {
    if (this.filtros.precio && this.filtros.peso) {
      // Ambos filtros están presentes, aplicar ambos
      this.piensoService.getPiensosConFiltros(this.filtros).subscribe(
        piensos => this.piensoService.piensos = piensos,
        error => console.error('Error al obtener piensos filtrados', error)
      );
    } else if (this.filtros.precio || this.filtros.peso) {
      // Solo uno de los filtros está presente, aplicar el filtro presente
      this.piensoService.getPiensosConFiltros(this.filtros).subscribe(
        piensos => this.piensoService.piensos = piensos,
        error => console.error('Error al obtener piensos filtrados', error)
      );
    } else {
      // Ningún filtro presente, mostrar todos los productos
      this.mostrarTodosLosProductos();
    }
  }







  cambiarFiltroPrecio(rangoPrecio: string) {
    this.activadoPrecio = !this.activadoPrecio;
    if (this.activadoPrecio) {
      this.filtros.precio = rangoPrecio;
    } else {
      this.filtros.precio = '';
    }
    this.actualizarProductos();
  }


  cambiarFiltroPeso(rangoPeso: string) {
    this.activadoPeso = !this.activadoPeso;
    if (this.activadoPeso) {
      this.filtros.peso = rangoPeso;
    } else {
      this.filtros.peso = '';
    }
    this.actualizarProductos();
  }








  actualizarProductos() {
    if (this.activadoPrecio || this.activadoPeso) {
      // Si al menos una casilla está marcada, aplicar los filtros y guardar los productos actuales
      this.productosAnteriores = this.piensoService.piensos;
      this.piensoService.getPiensosConFiltros(this.filtros).subscribe(
        piensos => this.piensoService.piensos = piensos,
        error => console.error('Error al obtener piensos filtrados', error)
      );
    } else {
      // Si ambas casillas están desmarcadas, mostrar todos los productos
      this.piensoService.getPiensos().subscribe(
        piensos => this.piensoService.piensos = piensos,
        error => console.error('Error al obtener todos los piensos', error)
      );
    }
  }


  //ESTO ES POR EL TIPO DE ANIMAL --> METODO PARA FILTRAL EL PIENSO DE ANIMAL QUE LE PASAS POR PARAMETRO
  filtrarPorTipo(tipoAnimal: string) {
    this.piensoService.getPiensosPorTipo(tipoAnimal).subscribe(
      piensos => this.piensoService.piensos = piensos,
      error => console.error('Error al obtener piensos filtrados', error)
    );
  }



  }





<!--TODOS LOS PRODUCTOS-->
<br>
<li class="list-group-item" style="color: #f79191; font-weight: bold; font-size: 1.2em; margin-left: 13px;">Todos</li>

<li class="list-group-item">
  <a (click)="mostrarTodosLosProductos()" style="text-decoration: none; cursor: pointer; color: blue; margin-left: 15px;">Ver todos los productos</a>
</li>


<br>
<ul class="list-group list-group-flush" style="margin-bottom: 7%;">
  <li class="list-group-item" style="color: #f79191; font-weight: bold; font-size: 1.2em;">Perros</li>
  <li class="list-group-item">
    <a (click)="filtrarPorTipo('Perro')" style="text-decoration: none; cursor: pointer; color: blue;">Comida para perros</a>
  </li>
</ul>



<ul class="list-group list-group-flush">
  <li class="list-group-item" style="color: #f79191; font-weight: bold; font-size: 1.2em;">Gatos</li>
  <li class="list-group-item">
    <a (click)="filtrarPorTipo('Gato')" style="text-decoration: none; cursor: pointer; color: blue;">Comida para gatos</a>
  </li>
</ul>



<br>
<ul class="list-group list-group-flush" style="margin-bottom: 7%;">
  <li class="list-group-item" style="color: #f79191; font-weight: bold; font-size: 1.2em;">Roedores</li>
  <li class="list-group-item">
    <a (click)="filtrarPorTipo('Roedor')" style="text-decoration: none; cursor: pointer; color: blue;">Comida para roedores</a>
  </li>
</ul>



<ul class="list-group list-group-flush" style="margin-bottom: 7%;">
  <li class="list-group-item" style="color: #f79191; font-weight: bold; font-size: 1.2em;">Pajaros</li>
  <li class="list-group-item">
    <a (click)="filtrarPorTipo('Pajaro')" style="text-decoration: none; cursor: pointer; color: blue;">Comida para pajaros</a>
  </li>
</ul>



    <!--BOTONES DE PRECIO-->
    <li class="list-group-item" style="color: #f79191; font-weight: bold; font-size: 1.2em;margin-left: 13px;">Precios</li>

    <!-- Input de Rango de Precios Personalizado
    <div style="display: flex; align-items: center; margin-bottom: 15px;">
      <input type="text" placeholder="Mín" style="margin-right: 5px; width: 50px; font-size: 14px;"/>
      <span>-</span>
      <input type="text" placeholder="Máx" style="margin-left: 5px; width: 50px; font-size: 14px; margin-right: 10px;"/>
      <button type="button" class="btn btn-primary">Buscar</button>
    </div>-->


    <div class="form-check">
      <input type="checkbox" id="precio1" name="grupo1"  [checked]="precioSeleccionado === '0-10'"   (click)="cambiarFiltroPrecio('0-10')" >
      <label for="precio1"> 0 - 10</label>
    </div>


    <div class="form-check">
      <input type="checkbox" id="precio2" name="grupo1"  [checked]="precioSeleccionado === '11-20'"  (click)="cambiarFiltroPrecio('11-20')" >
      <label for="precio1"> 11 - 20</label>
    </div>


    <div class="form-check">
      <input type="checkbox" id="precio3" name="grupo1"  [checked]="precioSeleccionado === '21-30'"  (click)="cambiarFiltroPrecio('21-30')" >
      <label for="precio1"> 21 - 30</label>
    </div>


    <div class="form-check">
      <input type="checkbox" id="precio4" name="grupo1"  [checked]="precioSeleccionado === '31-40'"  (click)="cambiarFiltroPrecio('31-40')" >
      <label for="precio1"> 31 - 40</label>
    </div>


    <div class="form-check">
      <input type="checkbox" id="precio5" name="grupo1"  [checked]="precioSeleccionado === '41-50'"  (click)="cambiarFiltroPrecio('41-50')" >
      <label for="precio1"> 41 - 50</label>
    </div>


    <div class="form-check">
      <input type="checkbox" id="precio6" name="grupo1"  [checked]="precioSeleccionado === '51-0'"  (click)="cambiarFiltroPrecio('51-70')" >
      <label for="precio1"> 51 - 70</label>
    </div>




    <!--BOTONES DE PESO-->
    <li class="list-group-item" style="color: #f79191; font-weight: bold; font-size: 1.2em; margin-left: 13px;">Peso</li>


    <!-- Input de Rango de Peso Personalizado
    <div style="display: flex; align-items: center; margin-bottom: 15px;">
      <input type="text" placeholder="Mín" style="margin-right: 5px; width: 50px; font-size: 14px;"/>
      <span>-</span>
      <input type="text" placeholder="Máx" style="margin-left: 5px; width: 50px; font-size: 14px; margin-right: 10px;"/>
      <button type="button" class="btn btn-primary">Buscar</button>
    </div>-->


    <div class="form-check">
      <input type="checkbox" id="peso1" name="grupo2" [checked]="pesoSeleccionado" (click)="cambiarFiltroPeso('0-5')">
