    <!--METODOS EN JAVASCRIPT PARA SELECCIONAR SOLO UN CHECKBOX Y QUE EL ANTERIOR SE QUITE-->

    <script>
      document.addEventListener("DOMContentLoaded", function() {
        // Función para manejar los cambios en los checkboxes de un grupo específico
        function handleCheckboxChange(groupName) {
            // Obtenemos todos los checkboxes del grupo especificado
            const checkboxes = document.querySelectorAll(`input[name="${groupName}"]`);

            // Añadimos manejadores de eventos para cada checkbox
            checkboxes.forEach(function(checkbox) {
                checkbox.addEventListener('change', function() {
                    // Si el checkbox está marcado, desmarcamos los otros en el mismo grupo
                    if (checkbox.checked) {
                        checkboxes.forEach(function(otherCheckbox) {
                            if (otherCheckbox !== checkbox) {
                                otherCheckbox.checked = false;
                            }
                        });
                    }
                });
            });
        }

        // Ejecutamos la función para los grupos de precios y pesos
        handleCheckboxChange('grupo1'); // Para precios
        handleCheckboxChange('grupo2'); // Para pesos
      });
    </script>
